import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {describe, it, expect} from 'vitest';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
  workspaceId: 'w1',
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator onError on non-Error rejections (unit)', () => {
  it('calls onError when provider rejects with a string', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith('string boom'), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toBe('string boom');

    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('string boom');
    expect(receivedError?.cause).toBe('string boom');
  });

  it('calls onError when provider rejects with a plain object', async () => {
    let receivedError: Error | undefined;
    const reason = {code: 503, detail: 'upstream down'};
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toEqual(reason);

    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toContain('upstream down');
    expect(receivedError?.cause).toBe(reason);
  });
});

